import { describe, it, expect, afterEach } from 'vitest'
import { render, screen, cleanup, within } from '@testing-library/react'
import '@testing-library/project/src/file361'
import App from '../App'

// 课程页两级分类：理论课 / 实践课，实践课并入训练营
describe('课程页两级分类', () => {
  it('理论课一节含体系课程，不含实践内容', () => {
    window.history.pushState({}, '', '/courses')
    render(<App />)
    const theory = screen.getByRole('heading', { name: '理论课' }).closest('section') as HTMLElement
    expect(within(theory).getByText('大数据导论')).toBeInTheDocument()
    expect(within(theory).getByText('知识工作')).toBeInTheDocument()
    expect(within(theory).queryByText('生产实习')).toBeNull()
    expect(within(theory).queryByText('智能体工程师训练营')).toBeNull()
  })

  it('实践课一节含生产实习与训练营', () => {
    window.history.pushState({}, '', '/courses')
    render(<App />)
    const practice = screen.getByRole('heading', { name: '实践课' }).closest('section') as HTMLElement
    expect(within(practice).getByText('生产实习')).toBeInTheDocument()
    expect(within(practice).getByText('智能体工程师训练营')).toBeInTheDocument()
    expect(within(practice).queryByText('数据工程')).toBeNull()
  })

  it('训练营卡片跳转训练营详情', () => {
    window.history.pushState({}, '', '/courses')
    render(<App />)
    const practice = screen.getByRole('heading', { name: '实践课' }).closest('section') as HTMLElement
    const link = within(practice).getByRole('link', { name: /智能体工程师训练营/ })
    expect(link).toHaveAttribute('href', '/project/src/file362')
  })
})

afterEach(cleanup)

import { describe, it, expect, afterEach } from 'vitest'
import { render, screen, cleanup } from '@testing-library/react'
import '@testing-library/project/src/file361'
import App from '../App'

// 学习页价格分档：三档卡片在上，C 档明细两篇原样可达
describe('学习页价格分档', () => {
  it('prices 板块渲染三档', () => {
    window.history.pushState({}, '', '/learn')
    render(<App />)
    expect(screen.getByText('G 端 · 校企合作')).toBeInTheDocument()
    expect(screen.getByText('B 端 · 企业培训与人才交付')).toBeInTheDocument()
    expect(screen.getByText('C 端 · 个人学习')).toBeInTheDocument()
  })

  it('C 档下原有两篇价格明细可达', () => {
    window.history.pushState({}, '', '/learn')
    render(<App />)
    const consultation = screen.getByRole('link', { name: /一对一咨询定价/ })
    expect(consultation).toHaveAttribute('href', '/project/src/file364')
    const freeParticipation = screen.getByRole('link', { name: /任务参与免费/ })
    expect(freeParticipation).toHaveAttribute('href', '/project/src/file365')
  })

  it('三档不带价格数字', () => {
    window.history.pushState({}, '', '/learn')
    const { container } = render(<App />)
    const tracks = ['G 端 · 校企合作', 'B 端 · 企业培训与人才交付', 'C 端 · 个人学习']
    for (const label of tracks) {
      const card = screen.getByText(label).closest('.learnCard') as HTMLElement
      expect(card, label).toBeTruthy()
      expect(card.textContent, label).not.toMatch(/\d+\s*元/)
    }
    expect(container).toBeTruthy()
  })
})

afterEach(cleanup)

import { BrowserRouter, Routes, Route } from 'react-router-dom'
import Home from './project/src/file373'
import Course from './project/src/file374'
import Prices from './project/src/file375'
import ItemDetail from './project/src/file376'
import Layout from './project/src/file377'
import { ROUTE_PATHS } from './routes'
import './App.css'

// 路由表单独导出，便于在 MemoryRouter 下测试
export function AppRoutes() {
  return (
    <Routes>
      <Route path={ROUTE_PATHS.home} element={<Home />} />
      <Route path={ROUTE_PATHS.course} element={<Course />} />
      <Route path={ROUTE_PATHS.prices} element={<Prices />} />
      <Route path={ROUTE_PATHS.scheduleItem} element={<ItemDetail />} />
    </Routes>
  )
}

function App() {
  return (
    <BrowserRouter>
      <Layout>
        <AppRoutes />
      </Layout>
    </BrowserRouter>
  )
}

export default App

import { useEffect, useState } from 'react'
import Markdown from '../project/src/file379'
import {
  PRICES_TRACKS,
  itemsIn,
  learningEntries,
  loadLearningEntries,
  type LearningEntry,
} from '../project/src/file355'

// 价格页：三档付费对象在上（询价口径不标价格），C 档明细两篇内联
function Prices() {
  const [entries, setEntries] = useState<LearningEntry[]>(learningEntries)

  useEffect(() => {
    let alive = true
    loadLearningEntries().then((next) => {
      if (alive) setEntries(next)
