}

export default Prices

import { useParams, Link } from 'react-router-dom'
import { useEffect, useState } from 'react'
import Markdown from '../project/src/file381'
import {
  getLearningEntry,
  learningEntries,
  loadLearningEntries,
  sectionOf,
  type LearningEntry,
} from '../project/src/file382'
import { ROUTE_PATHS } from '../project/src/file383'

// 训练营详情：正文原样渲染（来源行随任务下线不再转链）
function ItemDetail() {
  const { slug } = useParams()
  const [entries, setEntries] = useState<LearningEntry[]>(learningEntries)

  useEffect(() => {
    let alive = true
    loadLearningEntries().then((next) => {
      if (alive) setEntries(next)
    })
    return () => {
      alive = false
    }
  }, [])

  const entry = slug ? getLearningEntry('schedules', slug, entries) : undefined

  if (!entry) {
    return (
      <main>
        <div className="not-found">
          <h2>内容未找到</h2>
          <p>请返回课程页面查看全部内容。</p>
          <Link to={ROUTE_PATHS.course} className="primaryLink">
            返回课程
          </Link>
        </div>
      </main>
    )
  }

  return (
    <main>
