import { Link, useLocation, useNavigate } from 'react-router-dom'
import { ROUTE_PATHS, isTabPath } from '../routes'

// 顶部 AppBar（微信式）：页签根页居中标题；压入页（详情/反馈）左侧返回——
// 有历史可退则弹栈，深链直达则回实践
function AppBar() {
  const { pathname } = useLocation()
  const navigate = useNavigate()
  const onTab = isTabPath(pathname)

  const goBack = () => {
    if ((window.history.state?.idx ?? 0) > 0) {
      navigate(-1)
    } else {
      navigate(ROUTE_PATHS.practice)
    }
  }

  return (
    <header className="appBar">
      {onTab ? (
        <span className="appBarSlot" aria-hidden="true" />
      ) : (
        <Link to={ROUTE_PATHS.practice} className="appBarBack" aria-label="返回" onClick={(event) => {
          if ((window.history.state?.idx ?? 0) > 0) {
            event.preventDefault()
            navigate(-1)
          }
        }}>
          <svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true">
            <path
              d="M15 5l-7 7 7 7"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.8"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </Link>
      )}
      <h1 className="appBarTitle">量潮课堂</h1>
      <span className="appBarSlot" aria-hidden="true" />
    </header>
  )
}

export default AppBar

import {
  ACCEPTANCES,
  REQUIREMENTS,
  type AcceptanceFilter,
  type RequirementFilter,
} from '../project/src/file430'

interface FilterSheetProps {
  requirement: RequirementFilter
  acceptance: AcceptanceFilter
  onRequirement: (value: RequirementFilter) => void
  onAcceptance: (value: AcceptanceFilter) => void
  onClose: () => void
}

// 底部弹层筛选（微信式）：两组选项各带「全部」，点选即生效并收起
function FilterSheet({
  requirement,
  acceptance,
  onRequirement,
  onAcceptance,
  onClose,
}: FilterSheetProps) {
  return (
    <div className="sheetOverlay" onClick={onClose} role="presentation">
      <div
        className="sheet"
        role="dialog"
        aria-label="筛选"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="sheetGroup">
          <p className="sheetGroupTitle">需求的精确程度</p>
          <div className="sheetOptions">
            <button
              type="button"
              className={`sheetOption${requirement === 'all' ? ' active' : ''}`}
              onClick={() => {
                onRequirement('all')
                onClose()
              }}
            >
              全部
            </button>
            {REQUIREMENTS.map((item) => (
              <button
                key={item.value}
                type="button"
                className={`sheetOption${requirement === item.value ? ' active' : ''}`}
                onClick={() => {
                  onRequirement(item.value)
                  onClose()
                }}
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>
        <div className="sheetGroup">
          <p className="sheetGroupTitle">验收标准的开放程度</p>
          <div className="sheetOptions">
            <button
              type="button"
              className={`sheetOption${acceptance === 'all' ? ' active' : ''}`}
              onClick={() => {
                onAcceptance('all')
                onClose()
              }}
            >
              全部
            </button>
            {ACCEPTANCES.map((item) => (
              <button
                key={item.value}
                type="button"
                className={`sheetOption${acceptance === item.value ? ' active' : ''}`}
                onClick={() => {
                  onAcceptance(item.value)
                  onClose()
                }}
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>
        <button type="button" className="sheetCancel" onClick={onClose}>
          取消
        </button>
      </div>
    </div>
  )
}

export default FilterSheet

import { useState } from 'react'
import { Link } from 'react-router-dom'
import FilterSheet from '../project/src/file883'
import {
  CURRENT_TASKS,
  acceptanceLabel,
  requirementLabel,
  statusLabel,
  taskbooks,
  type AcceptanceFilter,
  type RequirementFilter,
} from '../project/src/file430'
import { taskItemPath } from '../routes'

// 实践页：任务书库（当前指派在前）+ 顶部两把尺筛选。学员在做，不在看
function Practice() {
  const [requirement, setRequirement] = useState<RequirementFilter>('all')
  const [acceptance, setAcceptance] = useState<AcceptanceFilter>('all')
  const [sheetOpen, setSheetOpen] = useState(false)

  const currentSlugs = CURRENT_TASKS.map((task) => task.slug)
  const ordered = [...taskbooks].sort((a, b) => {
    const ai = currentSlugs.indexOf(a.slug)
    const bi = currentSlugs.indexOf(b.slug)
    if (ai !== -1 || bi !== -1) return (ai === -1 ? Infinity : ai) - (bi === -1 ? Infinity : bi)
    return a.slug.localeCompare(b.slug)
  })
  const books = ordered.filter(
    (book) =>
      (requirement === 'all' || book.tags.requirement === requirement) &&
      (acceptance === 'all' || book.tags.acceptance === acceptance),
  )

  const summary = [
    requirement !== 'all' ? `需求：${requirementLabel(requirement)}` : null,
    acceptance !== 'all' ? `验收：${acceptanceLabel(acceptance)}` : null,
  ]
    .filter(Boolean)
    .join(' · ')

  return (
    <main>
      <div className="filterBar">
        <button type="button" className="filterEntry" onClick={() => setSheetOpen(true)}>
          {summary || '筛选'}
          <span className="filterCaret" aria-hidden="true">
            ▾
          </span>
        </button>
      </div>

      {books.length === 0 && <p className="todayHint">没有符合筛选条件的任务书。</p>}

      {books.map((book) => {
        const task = CURRENT_TASKS.find((item) => item.slug === book.slug)
        const tags = [
          book.tags.requirement ? `需求：${requirementLabel(book.tags.requirement)}` : null,
          book.tags.acceptance ? `验收：${acceptanceLabel(book.tags.acceptance)}` : null,
        ].filter(Boolean)
        return (
          <Link key={book.slug} to={taskItemPath(book.slug)} className="taskCard">
            <div className="taskCardTop">
              <h2>{book.title}</h2>
              {task && (
                <span className={`taskStatus ${task.status}`}>{statusLabel(task.status)}</span>
              )}
            </div>
            <p className="taskDesc">{task?.description || book.description}</p>
            {task && <p className="taskDeadline">截止：{task.deadline}</p>}
            {tags.length > 0 && <p className="taskTags">{tags.join(' · ')}</p>}
          </Link>
        )
      })}

      {sheetOpen && (
        <FilterSheet
          requirement={requirement}
          acceptance={acceptance}
          onRequirement={setRequirement}
          onAcceptance={setAcceptance}
          onClose={() => setSheetOpen(false)}
        />
      )}
    </main>
  )
}

export default Practice

